# tests/test_safe_divide.py
import math

import pytest

from your_module import safe_divide  # Replace "your_module" with the actual module name


@pytest.mark.parametrize(
    ("a", "b", "expected"),
    [
        (6.0, 3.0, 2.0),
        (5.0, 2.0, 2.5),
        (-6.0, 3.0, -2.0),
        (6.0, -3.0, -2.0),
        (-6.0, -3.0, 2.0),
        (0.0, 5.0, 0.0),
        (1.0, 3.0, 1.0 / 3.0),
    ],
)
def test_safe_divide_returns_quotient(a, b, expected):
    assert safe_divide(a, b) == pytest.approx(expected)


@pytest.mark.parametrize("b", [0, 0.0, -0.0])
def test_safe_divide_zero_denominator_returns_default_value(b):
    assert safe_divide(10.0, b) == 0.0


@pytest.mark.parametrize(
    ("a", "b", "default"),
    [
        (10.0, 0.0, -1.0),
        (-10.0, 0.0, 99.5),
        (0.0, 0.0, 123.0),
    ],
)
def test_safe_divide_zero_denominator_returns_custom_default(a, b, default):
    assert safe_divide(a, b, default=default) == default


def test_safe_divide_handles_float_edge_values():
    assert safe_divide(math.inf, 2.0) == math.inf
    assert safe_divide(1.0, math.inf) == 0.0
    assert math.isnan(safe_divide(math.nan, 2.0))


@pytest.mark.parametrize(
    ("a", "b"),
    [
        ("10", 2.0),
        (10.0, "2"),
        (None, 2.0),
        (10.0, None),
    ],
)
def test_safe_divide_invalid_operand_types_raise_type_error(a, b):
    with pytest.raises(TypeError):
        safe_divide(a, b)


def test_safe_divide_only_catches_zero_division_error():
    with pytest.raises(TypeError):
        safe_divide("10", 0, default=-1.0)
